with p as (select id from liq_proveedores where nombre='UBS')
update liq_proveedores set email_patron=null, email_patron_fuente=' · confianza: baja',
 canales_publicos='[{"canal": "Comunicado oficial UBS Tokenize / uMINT (transacción con Chainlink DTA, nov 2025)", "valor": "https://www.ubs.com/global/fr/media/display-page-ndp/en-20251104-chainlink.html", "fuente": "https://www.ubs.com/global/fr/media/display-page-ndp/en-20251104-chainlink.html"}, {"canal": "Media Relations Suiza (teléfono; email solo vía enlace en la página)", "valor": "+41 44 234 85 00", "fuente": "https://www.ubs.com/global/en/media/contact.html"}, {"canal": "Media Relations Américas (teléfono)", "valor": "+1 212 882 5858", "fuente": "https://www.ubs.com/global/en/media/contact.html"}, {"canal": "LinkedIn empresa", "valor": "https://www.linkedin.com/company/ubs", "fuente": "https://www.linkedin.com/company/ubs"}, {"canal": "X / Twitter", "valor": "@UBS", "fuente": "https://x.com/UBS"}, {"canal": "Canal indirecto: DigiFT, distribuidor autorizado de uMINT (mayor distribuidor por volumen)", "valor": "DigiFT", "fuente": "https://www.aap.com.au/aapreleases/cision20241102ae46289"}]'::jsonb, ruta_recomendada='1) Primer correo a Laurens Schepens (Product Lead UBS Tokenize) con CC a Simon Basler (Head of Digital Assets Initiative Development, Zúrich); proponer cross-listing/distribución secundaria de uMINT u otros productos UBS Tokenize hacia Centroamérica vía Kabal Digital Marketplace. Sin email verificado: contactar por LinkedIn InMail o solicitar el contacto a Media Relations Suiza. 2) Intro cálida en paralelo vía DigiFT (distribuidor autorizado de uMINT) o Chainlink (socio del estándar DTA en la transacción de nov 2025); Copper y Bybit también forman parte del ecosistema uMINT. 3) Si no hay respuesta en ~10 días, escalar a Andreas Kubli (Group Head of Digital Assets desde marzo 2026, decisor) y, para el ángulo regional, pedir referencia interna a Marcello Chilov (Head WM Latin America) o directamente a Simon Toros (head de CAS: Centroamérica, Andes y Cono Sur, reporta a Chilov según la reorganización de marzo 2026). 4) Fallback: Media Relations Suiza +41 44 234 85 00 o la página LinkedIn de UBS para pedir el canal de partnerships de UBS Tokenize.',
 decisor=coalesce('Laurens Schepens — Product Lead, UBS Tokenize y Regional Digital Asset Lead APAC',decisor), contacto_email=coalesce(contacto_email,null),
 notas=coalesce(notas,'')||E'\n[Contactos '||to_char(now(),'YYYY-MM-DD')||'] Programa: '||'UBS Tokenize / uMINT; socio del ecosistema DigiFT; distribución de fondos tokenizados.'||E'\n'||'Investigación automática 2026-10-18 (lote EXPLORE del Liquidity Agent): agente de búsqueda + verificación adversarial de roles y correos; 15 búsquedas. Todo correo con patron_no_verificado debe confirmarse antes de enviar.'
where id=(select id from p);
insert into liq_contactos (proveedor_id,nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
select (select id from liq_proveedores where nombre='UBS'), v.* from (values
('Laurens Schepens','Product Lead, UBS Tokenize y Regional Digital Asset Lead APAC','UBS Tokenize / Digital Assets','Singapur',null,null,'desconocido','dueno_programa',1,'Lidera el producto UBS Tokenize, la plataforma que emite uMINT; es quien evaluaría un cross-listing o distribución secundaria de productos tokenizados de UBS.','https://www.fintechfestival.sg/speakers/spkr8331-laurens-schepens','Verificación: el perfil vigente del Singapore FinTech Festival y la página de Chainlink SmartCon (''Lead UBS Tokenize'', https://smartcon.chain.link/recordings/the-future-of-tokenized-fund-operations) confirman el rol; no se halló evidencia de salida ni cambio de cargo en 2025-2026 (un perfil archivado de 2023 lo listaba como ''CoE Lead Digital Assets, UBS Tokenize''). La página no pudo abrirse desde el entorno (bloqueo DNS) pero sigue indexada. Basado en APAC, no cubre LatAm. Sin email publicado en ninguna fuente.'),
('Andreas Kubli','Group Head of Digital Assets','Group Digital Assets (estrategia grupal de activos digitales y tokenización)','Zúrich, Suiza',null,null,'desconocido','decisor',2,'Dirige la estrategia grupal de activos digitales y tokenización de UBS desde marzo 2026; puede aprobar una alianza de distribución o liquidez.','https://www.pointzeroforum.com/speakers/spkr15289-andreas-kubli','Verificación: la biografía de ponente en Point Zero Forum indica que fue nombrado Group Head of Digital Assets el 1 de marzo de 2026, tras dirigir Channels & Platforms / Multichannel Management & Digitalisierung en UBS Switzerland (2013-2026; finews.ch/news/banken/22270). Fuente corregida: la anterior apuntaba al perfil de Jason Willi en The Big Whale, que solo lo menciona. No se localizó comunicado oficial de UBS; el rol es muy reciente. Sin email publicado.'),
('Simon Basler','Head of Digital Assets Initiative Development','Digital Assets Center of Excellence (grupo)','Zúrich, Suiza',null,null,'desconocido','dueno_programa',3,'Lidera el desarrollo de iniciativas de activos digitales dentro del Centro de Excelencia grupal; interlocutor natural en Suiza para una propuesta de partnership.','https://www.pointzeroforum.com/speakers/spkr3202-dr-simon-basler','Verificación: el perfil de ponente en la edición vigente de Point Zero Forum (y la archivada de 2024) confirma ''Head of Digital Assets Initiative Development''; The Big Whale lo lista como ''Lead Digital Assets Development''. Sin evidencia de cambio de rol en 2025-2026. Sin email publicado.'),
('Jason Willi','Initiative Lead – Digital Assets & Money','Digital Assets & Money (sede Zúrich)','Zúrich, Suiza',null,null,'desconocido','entrada',4,'Rol operativo reciente (desde sept 2025) en las iniciativas de activos digitales y dinero digital en la sede; punto de entrada alterno si Schepens no responde.','https://www.thebigwhale.io/peoples/jason-willi','Verificación: la página de The Big Whale está indexada e indica ''Initiative Lead – Digital Assets & Money'', Zúrich, desde sept 2025, pero su biografía mezcla texto de otra persona (Josh Hershman), por lo que es poco fiable; no hay fuente oficial de UBS. Se mantiene en prioridad baja hasta confirmar en LinkedIn. Sin email publicado.'),
('Xiaonan Zou','Head of Digital Assets, UBS Group Treasury','Group Treasury – Digital Assets (UBS Digital Cash)','Londres, Reino Unido',null,null,'desconocido','influencer',5,'Construyó el equipo de activos digitales de Tesorería (dinero digital y liquidación); relevante para una facilidad programática o liquidación, no para distribución de fondos.','https://www.thebigwhale.io/peoples/xiaonan-zou','Verificación: The Big Whale confirma ''Head of Digital Assets, UBS Group Treasury'' (lidera el equipo en Londres desde dic 2019); sin evidencia de cambio. Directorio de terceros; foco en tesorería/digital cash más que en distribución de productos tokenizados. Sin email publicado.'),
('Marcello Chilov','Head of Global Wealth Management Latin America','Global Wealth Management – Latin America','Brasil (LatAm)',null,null,'desconocido','cobertura_latam',5,'Responsable de wealth management en LatAm; útil solo para referencia interna hacia el equipo de activos digitales y para validar apetito regional.','https://braziljournal.com/no-ubs-chilov-reorganiza-wealth-management-gross-vai-liderar-brasil/','Verificación: vigente. La reorganización de UBS Wealth Management LatAm del 2 de marzo de 2026 (Brazil Journal; también portaltela.com) lo confirma como head de WM para la región, con todos los country heads reportándole: Rafael Gross (Brasil), Daniel Parra (México), Simon Toros (CAS: Centroamérica, Andes y Cono Sur) y Jan Martin Sommer (Argentina). Fuente actualizada de 2023 a 2026. Para Honduras/Centroamérica, Simon Toros (head CAS) es el referente directo bajo Chilov. No es del área de activos digitales. Sin email publicado.')) as v(nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
on conflict (proveedor_id, lower(nombre)) do update set cargo=excluded.cargo, area=excluded.area, ubicacion=excluded.ubicacion,
 linkedin=coalesce(excluded.linkedin,liq_contactos.linkedin), email=coalesce(excluded.email,liq_contactos.email), email_estado=excluded.email_estado,
 rol=excluded.rol, prioridad=excluded.prioridad, por_que=excluded.por_que, fuente=excluded.fuente, notas=excluded.notas;
